def get_schema(schema_tuples: List[Union[Tuple[str, str, str, bool], Tuple[str, str, str, bool, str]]]) -> List[Dict[str, Any]]:
    """
    Convert a list of schema tuples to a list of schema dictionaries.

    Each tuple can have 4 or 5 elements:
    - (name, type, jsonpath, has_default) - original format
    - (name, type, jsonpath, has_default, encoding) - new format with optional encoding

    Returns a list of dictionaries with keys: name, type, jsonpath, has_default, and optionally encoding
    """
    schema_rowbinary = []
    for schema_tuple in schema_tuples:
        if len(schema_tuple) == 4:
            name, type_name, jsonpath, has_default = schema_tuple
            schema_column = {
                'name': name,
                'type': type_name,
                'jsonpath': jsonpath,
                'has_default': has_default
            }
        elif len(schema_tuple) == 5:
            name, type_name, jsonpath, has_default, encoding = schema_tuple
            schema_column = {
                'name': name,
                'type': type_name,
                'jsonpath': jsonpath,
                'has_default': has_default,
                'encoding': encoding
            }
        else:
            raise ValueError(f"Schema tuple must have 4 or 5 elements, got {len(schema_tuple)}")

        schema_rowbinary.append(schema_column)
    return schema_rowbinary


