    def test_convert_to_row_binary_large_value(self):
        schema = [('date', 'DateTime64', "$.date", False), ('value', 'String', "$.value", False)]
        schema_rowbinary = get_schema(schema)
        schema_rowbinary = json.dumps(schema_rowbinary)

        large_value = "".join(random.choices(string.ascii_uppercase + string.digits, k=int(10 * MB / 2)))
        data = '{"date": "2020-06-13 22:07:41.123", "value": "' + large_value + '"}\n'

        # maximum capacity can be adjusted
        with chquery.RowBinaryEncoder(schema_rowbinary, max_json_row_size=len(data)) as encoder:
            result, quarantine, nrows, nquarantine = encoder.encode(data)

            assert result != b''
            assert quarantine == b''
            assert nrows == 1
            assert nquarantine == 0

        # if row is larger than the maximum capacity it goes to quarantine
        with chquery.RowBinaryEncoder(schema_rowbinary, max_json_row_size=1000000) as encoder:
            result, quarantine, nrows, nquarantine = encoder.encode(data)

            assert result == b''
            assert quarantine != b''
            assert nrows == 0
            assert nquarantine == 1

            expected_quarantine_prefix = b'\x01\x01\x00\x01\xec\x80\xc0\x02CAPACITY:'
            assert quarantine[0:len(expected_quarantine_prefix)] == expected_quarantine_prefix

